-module(otp_gui478_observer).
-export([worker/1,run/0,debug_stack/2]).
-file("otp_gui478_observer.erl",1).
worker(Parent)->Parent!{finished,run()}.
run()->[observe(M,F,A)||{M,F,A}<-cases()].
observe(M,F,A)->try apply(M,F,A) of V->{{M,F,A},{returned,V}} catch C:R:S->{{M,F,A},{caught,C,R,S}} end.
debug_stack(Mode,Last)->
 erase(dbg_istk),put(trace_stack,Mode),
 Initial=dbg_istk:init(),
 I={ieval,1,42,example_mod,example_fun,[hello,2],[],false},
 Pushed=dbg_istk:push([{x,1}],I,Last),
 Level=dbg_istk:stack_level(),
 External=(dbg_istk:delayed_to_external())(),
 Popped=dbg_istk:pop(),
 Restored=dbg_istk:from_external(External),
 Before=get(dbg_istk),Trimmed=dbg_istk:pop(1),
 Result={Initial,Pushed,Level,External,Popped,Restored,Before,Trimmed,get(dbg_istk)},
 erase(trace_stack),erase(dbg_istk),Result.
